"""The header of a generated file and the safe read of a project-owned source file.

The header: (the rendered briefs since T-0206, the protocol's README.md and WORKER_BRIEF.md since
T-0219): one blockquote line that names the sources as the only places to edit and ends with `Body sha256 <16 hex>`, the
digest of the text below it (the pattern of tickets/ticket.env's `generated-from ... sha256` line), then a blank line.

A renderer decides per existing file from that line: one that is word for word the header it would write now, for these
sources, and whose digest matches the body, marks an untouched generated file, so a changed template, notes, docs or config
renders straight through; a missing, reworded or garbled header, one naming other sources, or a body that no longer
matches is a hand edit, refused until it is folded back into a source, and `--force` is for that case only. A hand edit
that also recomputes the digest passes: the header guards against a hand edit made by accident, which is accepted.
"""
from __future__ import annotations

import errno
import hashlib
import os
import stat

from zouinify import ZouinifyError

DIGEST_LEN = 16
LINE = ("> Generated by `{tool}` from {sources}. Do not edit this file: edit {those} and render again. "
        "Render refuses a hand-edited {noun}; `--force` only after the edit is folded back into a source. Body sha256 {digest}.")


def body_digest(body: str) -> str:
    return hashlib.sha256(body.encode("utf-8")).hexdigest()[:DIGEST_LEN]


def header_line(tool: str, sources: str, noun: str, those: str, digest: str) -> str:
    """The one line: `tool` is the command that renders the file, `sources` the markdown list of its inputs, `noun` what
    the file is called in the refusal ("brief", "file"), `those` how the sources are referred back to ("one of those two")."""
    return LINE.format(tool=tool, sources=sources, noun=noun, those=those, digest=digest)


def header(tool: str, sources: str, noun: str, those: str, body: str) -> str:
    """The header line for `body` and the blank line after it: prepend it to `body`."""
    return header_line(tool, sources, noun, those, body_digest(body)) + "\n\n"


def untouched(text: str, tool: str, sources: str, noun: str, those: str) -> bool:
    """True when `text` is a file this renderer wrote for exactly these sources and nobody edited it: its first line is,
    word for word, the header for its own body, and a blank line follows."""
    nl = text.find("\n")
    if nl < 0 or not text.startswith("> ") or text[nl + 1:nl + 2] != "\n":
        return False
    body = text[nl + 2:]
    return text[:nl] == header_line(tool, sources, noun, those, body_digest(body))


def read_project_text(root: str, rel: str, what: str, explicit: str | None = None) -> str | None:
    """A project-owned source file (`.ops/briefs.project/<role>.md`, `.ops/README.project.md`) read for splicing into a
    generated file, or None when it does not exist. Its text becomes part of a prompt or a protocol page, so it must be a
    plain file inside the realpath'd project root: a symlinked parent directory, a symlinked file, a non-file or anything
    resolving elsewhere is refused and never followed; the file is opened O_NOFOLLOW and the descriptor must be the regular
    file that was checked (same device and inode), so a swap between the check and the open is caught; a non-UTF-8 file is
    a clean error. A same-uid writer changing the bytes meanwhile is out of scope: it can write the file directly, so no
    check here would add anything. `what` names the kind of file in the messages ("project notes"). With `explicit`, the
    caller named the file itself (`--project-readme FILE`): that path is read instead of `<root>/<rel>`, the outside-root
    check does not apply (as with --out), the symlink, regular-file and UTF-8 refusals do, and a missing file is an error."""
    if explicit:
        p = os.path.abspath(os.path.expanduser(explicit))
        rel = explicit
    else:
        root = os.path.realpath(root)
        p = os.path.join(root, rel)
    parent = os.path.dirname(p)
    if os.path.islink(parent):
        shown = os.path.dirname(rel) if not explicit else parent
        raise ZouinifyError(f"{shown} is a symlink; {what} live under the project root only")
    if os.path.islink(p):
        raise ZouinifyError(f"{rel} is a symlink; {what} live under the project root only")
    if not os.path.lexists(p):
        if explicit:
            raise ZouinifyError(f"{rel}: not a file")
        return None
    if not os.path.isfile(p):
        raise ZouinifyError(f"{rel} exists and is not a regular file" if not explicit else f"{rel}: not a file")
    if not explicit:
        real = os.path.realpath(p)
        if not real.startswith(root + os.sep):
            raise ZouinifyError(f"{rel} resolves outside the project root ({real}); refusing to read it")
    try:
        checked = os.lstat(p)
        fd = os.open(p, os.O_RDONLY | os.O_NOFOLLOW)
    except OSError as e:
        if e.errno == errno.ELOOP:
            raise ZouinifyError(f"{rel} is a symlink; {what} live under the project root only") from None
        raise ZouinifyError(f"{rel}: {e.strerror}") from None
    try:
        opened = os.fstat(fd)
        if not stat.S_ISREG(opened.st_mode) or (opened.st_dev, opened.st_ino) != (checked.st_dev, checked.st_ino):
            raise ZouinifyError(f"{rel} changed while it was being read; run again")
        with os.fdopen(fd, encoding="utf-8") as fh:
            fd = -1
            return fh.read()
    except UnicodeDecodeError:
        raise ZouinifyError(f"{rel}: not UTF-8 text") from None
    finally:
        if fd >= 0:
            os.close(fd)
